import { getConfig } from "../../src/config/index.js";
import { enhanceAdapterWithFS, getEnv, isExtendedFSAdapter, } from "../../src/platform/index.js";
import { captureHostApiEnvironment, getHostEnv } from "../../src/platform/compat/process/env.js";
import { runtime } from "../../src/platform/adapters/registry.js";
import { applyQualifiedRuntimeAuth, resolveLinkedProjectSlug } from "./runtime-auth.js";
